Definition geom_eq (r r' : meta) : Prop :=
  m_mem r' = m_mem r /\ m_last_idx r' = m_last_idx r /\ m_freeable r' = m_freeable r
  /\ m_sizeclass r' = m_sizeclass r /\ m_maplen r' = m_maplen r.

